/// <summary>
/// Kurt Scerri - 03/03/2021
/// Replication of Microsoft class <c>BankPaymAdviceReportGenerator</c> due to internal class declarations
/// </summary>
public abstract class METBankPaymAdviceReportGenerator
{
    protected const Timezone GMT = Timezone::GMT_DUBLIN_EDINBURGH_LISBON_LONDON;

    protected METBankPaymAdviceTmpMap bankPaymAdviceTmp, bankPaymAdviceCustTmp;
    protected CompanyInfo companyInfo;
    protected LogisticsAddressing companyAddress;
    protected LedgerJournalTrans ledgerJournalTrans;
    protected int currentSessionId;
    protected str grouping;

    private Phone companyPhone;
    private Email companyEmail;

    private TeleFax companyTeleFax;
    private Bitmap companyImage;
    private NoYes isReportV2Enabled = NoYes::Yes;
    private guid executionContext;
    private Name companyName;

    // Bug 71343: Payment advice missing ABN information
    private CompanyCoRegNum companyAbn;

}

