    /// <summary>
    /// Deletes the data for the report.
    /// </summary>
    public void deleteReportData()
    {
        try
        {
            delete_from bankPaymAdviceTmp
                where ((bankPaymAdviceTmp.SessionId == currentSessionId)
                    || (bankPaymAdviceTmp.DateOfCreation < DateTimeUtil::getToday(GMT) - 2));

            delete_from bankPaymAdviceCustTmp
                where ((bankPaymAdviceCustTmp.SessionId == currentSessionId)
                    || (bankPaymAdviceCustTmp.DateOfCreation < DateTimeUtil::getToday(GMT) - 2));;
        }
        catch
        {
            info("@MET:BankPaymAdviceClearError");
        }
    }

    /// <summary>
    /// Processes the business logic for the report.
    /// </summary>
    /// <param name="_ledgerJournalTrans">
    /// A payment record.
    /// </param>
    public void generateReportData(LedgerJournalTrans _ledgerJournalTrans)
    {
        // Bug 71205: MET Payment advice report printed for each individual payment journal line
        // create a copy of _ledgerJournalTrans and retrieve the corresponding vendor account
        LedgerJournalTrans ledgerJournalTransLocal;
        _ledgerJournalTrans.copyTo(ledgerJournalTransLocal);
        DimensionValue vendAccount = DimensionAttributeValueCombination::find(ledgerJournalTransLocal.LedgerDimension).DisplayValue;
        
        ledgerJournalTrans = _ledgerJournalTrans;

        this.initCompanyInfo();

        this.findRecipient(_ledgerJournalTrans);
        this.findGrouping();

        // Bug 71205: MET Payment advice report printed for each individual payment journal line
        // we need to loop through all the same journal lines with the same vendor and payment reference to call findInvoicesAndCreateData
        //LedgerJournalTrans ledgerJournalTransLocal;
        DimensionAttributeValueCombination  dimensionAttributeValueCombination;

        while select ledgerJournalTrans 
            exists join dimensionAttributeValueCombination
               where dimensionAttributeValueCombination.RecId == ledgerJournalTrans.LedgerDimension
                  && dimensionAttributeValueCombination.DisplayValue == vendAccount
                  && ledgerJournalTrans.JournalNum == ledgerJournalTransLocal.JournalNum
                  && ledgerJournalTrans.PaymReference == ledgerJournalTransLocal.PaymReference
        {
            this.findInvoicesAndCreateData();
        }
    }

    /// <summary>
    /// Get Remitto contact deatils of company  MPJ-31578
    /// </summary>
    /// <param name = "_logisticsElectronicAddressMethodType">EmailPhone</param>
    /// <returns>emailPhone</returns>
    private LogisticsElectronicAddressLocator getRemitToCompanyPhoneEmail(LogisticsElectronicAddressMethodType _logisticsElectronicAddressMethodType)
    {
        dirPartyLocation                dirPartyLocation;
        logisticsElectronicAddress      logisticsElectronicAddress;
        logisticsElectronicAddressRole  logisticsElectronicAddressRole;
        logisticsLocationRole           logisticsLocationRole;

        select firstonly * from companyInfo
                where companyInfo.DataArea == curext()
            join dirPartyLocation
                    where dirPartyLocation.Party == companyInfo.RecId
            join logisticsElectronicAddress
                    where logisticsElectronicAddress.Location == dirPartyLocation.Location &&  logisticsElectronicAddress.Type == _logisticsElectronicAddressMethodType//(LogisticsElectronicAddressMethodType::Phone)
             join logisticsElectronicAddressRole
                    where logisticsElectronicAddressRole.ElectronicAddress == logisticsElectronicAddress.RecId
            join logisticsLocationRole
                    where logisticsLocationRole.RecId == logisticsElectronicAddressRole.LocationRole
                     && logisticsLocationRole.Name == strFmt("@MET:METStrfmt1",logisticsLocationRoleType::RemitTo);

        return logisticsElectronicAddress.Locator;
    }

    private void initCompanyInfo()
    {
       

        companyInfo = CompanyInfo::find();
        companyAddress = companyInfo.postalAddress().Address;
        //companyPhone = companyInfo.phone();
        companyTeleFax = companyInfo.teleFax();
        companyImage = CompanyImage::find(companyInfo.dataAreaId, tableNum(CompanyInfo), companyInfo.RecId).Image;

        companyName = companyInfo.name();

        // Bug 71343: Payment advice missing ABN information
        // MPJ-31578 is unselecting the companyInfo record :s
        companyAbn = companyInfo.CoRegNum;

        //MPJ-31578 Start
        companyPhone = this.getRemitToCompanyPhoneEmail(LogisticsElectronicAddressMethodType::Phone);
        companyEmail = this.getRemitToCompanyPhoneEmail(LogisticsElectronicAddressMethodType::Email);
        //MPJ-31578 Start   
    }

/// <summary>
/// Find the payment recipient.
/// </summary>
/// <param name = "_ledgerJournalTrans">The payment record.</param>
protected abstract void findRecipient(ledgerJournalTrans _ledgerJournalTrans)
{
}

/// <summary>
/// Find the report grouping.
/// </summary>
protected abstract void findGrouping()
{
}

/// <summary>
/// Find invoices related to the payment and insert the report information.
/// </summary>
protected abstract void findInvoicesAndCreateData()
{
}

/// <summary>
/// Populates <c>BankPaymAdviceVendTmp</c> and inserts the report information for a single invoice and related payment.
/// </summary>
protected void insertBankPaymAdviceTmp()
{
    this.populateBankPaymAdviceVendTemp();
    bankPaymAdviceTmp.insert();
}

private void populateBankPaymAdviceVendTemp()
{
    this.populateBankPaymAdviceTempCommonInfo();
    this.populateBankPaymAdviceTempPaymentInfo();
    this.populateBankPaymAdviceTempInvoiceInfo();
    
}

    /// <summary>
    /// Popualtes <c>BankPaymAdviceTmp</c> with report information that is independent of invoices and payment.
    /// </summary>
    protected void populateBankPaymAdviceTempCommonInfo()
    {
        bankPaymAdviceTmp.CompanyPhone = companyPhone;
        bankPaymAdviceTmp.CompanyTeleFax = companyTeleFax;
        bankPaymAdviceTmp.CompanyGiro = companyInfo.Giro;
        // Bug 71343: Payment advice missing ABN information
        // for some reasons companyInfo record is empty here, using class varaiable instead like email, phone etc...
        //bankPaymAdviceTmp.CompanyCoRegNum = companyInfo.CoRegNum;
        bankPaymAdviceTmp.CompanyCoRegNum = companyAbn;

        bankPaymAdviceTmp.PaymAdviceDate = DateTimeUtil::getSystemDate(DateTimeUtil::getUserPreferredTimeZone());
        bankPaymAdviceTmp.DateOfCreation = DateTimeUtil::getToday(GMT);
        bankPaymAdviceTmp.SessionId = currentSessionId;
        bankPaymAdviceTmp.Grouping = grouping;
        bankPaymAdviceTmp.CompanyEmail = companyEmail;  //MPJ-31578 


        if (isReportV2Enabled)
        {
            bankPaymAdviceTmp.setExecutionContext(executionContext);
        }
        else
        {
            bankPaymAdviceTmp.Image = companyImage;

            if (companyImage)
            {
                bankPaymAdviceTmp.PrintImage = NoYesCombo::Yes;
            }
            else
            {
                bankPaymAdviceTmp.PrintImage = NoYesCombo::No;
            }
        }

        bankPaymAdviceTmp.Image         = companyImage;
    }

/// <summary>
/// Populates <c>bankPaymAdviceTmp</c> with the payment information.
/// </summary>
protected abstract void populateBankPaymAdviceTempPaymentInfo()
{
}

